INSERT INTO `film` VALUES (7, '疯狂的麦克斯：狂暴女神 Furiosa: A Mad Max Saga', 'http://localhost:9090/files/download/film_crazy_max.webp', '影片讲述了复仇女神弗瑞奥萨（安雅·泰勒-乔伊 Anya Taylor-Joy 饰）惊心动魄的成长史。年轻的弗瑞奥萨从原本的家园被掠走，落入军阀狄门特斯（克里斯·海姆斯沃斯 Chris Hemsworth 饰）领导的帮派手中，在穿过荒原时，他们来到不死老乔（拉黑·休姆 Lachy H ulme 饰）所掌管的堡垒。在两位暴君争夺统治地位的同时，弗瑞奥萨必须在重重考验中活下来，并想方设法寻找回家的路；她也逐渐成长为利落酷飒的狂暴女神。', '2024', '乔治·米勒', '安雅·泰勒-乔伊 / 克里斯·海姆斯沃斯 / 汤姆·伯克 / 艾莉拉·布朗 / 乔治·谢夫佐夫 / 拉黑·休姆 / 约翰·霍华德 / 安格斯·桑普森 / 查理·弗雷泽 / 埃尔莎·帕塔奇 / 内森·琼斯 / 乔什·赫尔曼 / 大卫·菲尔德 / 拉赫尔·罗曼 / 戴维·科林斯 / 戈兰·D·克鲁特 / CJ·布隆菲尔德 / 马图斯 / 伊恩·罗伯茨', 4, '澳大利亚 / 美国', '英语', '2024-05-24', '148分钟', 'tt12037194');
INSERT INTO `film` VALUES (8, '凡间天使 Ordinary Angels ', 'http://localhost:9090/files/download/film_angel.webp', '灵感来自于一个令人难以置信的真实故事：一位美发师单枪匹马地召集整个社区来帮助一位丧偶的父亲拯救他病危小女儿的生命。', '2024', ' 乔·戈恩', '希拉里·斯万克 / 阿兰·里奇森 / 艾米丽·米切尔 / 天行者·休斯 / 塔玛拉·琼斯 / 唐·迈克 / 瑞恩·艾伦 / 德鲁·鲍威尔 / 邓普斯·布瑞克 / 艾米·阿克 / 埃里克·阿塔瓦尔 / 沙龙·巴杰 / 黛安娜·博特尔奥-若班斯基 / DJ·布拉德森 / 大卫·劳伦斯·布朗 / 特里斯坦·卡尔鲁奇 / 劳利格·克莱门茨 / 格温多琳·柯林斯', 9, '美国', '英语', '2024-02-23', '116分钟', 'tt4996328');
