INSERT INTO `film` VALUES (15, '无敌浩克 The Incredible Hulk', 'http://localhost:9090/files/download/incredible_hulk.webp', '科学家布鲁斯·班纳因暴露在伽马辐射下变成绿巨人浩克，他必须逃避军方追捕，同时寻找治愈方法。', '2008', '路易斯·莱特里尔', '爱德华·诺顿 / 丽芙·泰勒 / 蒂姆·罗斯 / 威廉·赫特', 4, '美国', '英语', '2008-06-13', '112分钟', 'tt0800080');
