INSERT INTO `film` VALUES (18, '美国队长：复仇者先锋 Captain America: The First Avenger', 'http://localhost:9090/files/download/captain_america1.webp', '二战期间，体弱多病的史蒂夫·罗杰斯被改造为超级士兵“美国队长”，必须阻止红骷髅利用宇宙魔方统治世界。', '2011', '乔·约翰斯顿', '克里斯·埃文斯 / 汤米·李·琼斯 / 雨果·维文 / 海莉·阿特维尔', 5, '美国', '英语', '2011-07-22', '124分钟', 'tt0458339');
