INSERT INTO `film` VALUES (21, '雷神2：黑暗世界 Thor: The Dark World', 'http://localhost:9090/files/download/thor2.webp', '雷神索尔与洛基联手，对抗黑暗精灵玛勒基斯，阻止以太粒子毁灭宇宙。', '2013', '艾伦·泰勒', '克里斯·海姆斯沃斯 / 娜塔莉·波特曼 / 汤姆·希德勒斯顿 / 安东尼·霍普金斯', 4, '美国', '英语', '2013-11-08', '112分钟', 'tt1981115');
