INSERT INTO `film` VALUES (23, '银河护卫队 Guardians of the Galaxy', 'http://localhost:9090/files/download/guardians1.webp', '彼得·奎尔与四个格格不入的宇宙罪犯组成联盟，共同拯救银河系。', '2014', '詹姆斯·古恩', '克里斯·帕拉特 / 佐伊·索尔达娜 / 戴夫·巴蒂斯塔 / 范·迪塞尔', 4, '美国', '英语', '2014-08-01', '121分钟', 'tt2015381');
INSERT INTO `film` VALUES (24, '复仇者联盟2：奥创纪元 Avengers: Age of Ultron', 'http://localhost:9090/files/download/avengers2.webp', '托尼·史塔克启动的维和计划“奥创”失控，复仇者联盟必须再次集结阻止全球毁灭。', '2015', '乔斯·韦登', '小罗伯特·唐尼 / 克里斯·埃文斯 / 克里斯·海姆斯沃斯 / 马克·鲁法洛', 4, '美国', '英语', '2015-05-01', '141分钟', 'tt2395427');
INSERT INTO `film` VALUES (25, '蚁人 Ant-Man', 'http://localhost:9090/files/download/antman1.webp', '斯科特·朗获得蚁人战服后拥有缩小身体、增大力量的能力，他必须帮助汉克·皮姆保护这项技术。', '2015', '佩顿·里德', '保罗·路德 / 迈克尔·道格拉斯 / 伊万杰琳·莉莉 / 寇瑞·斯托尔', 4, '美国', '英语', '2015-07-17', '117分钟', 'tt0478970');
INSERT INTO `film` VALUES (26, '美国队长3：内战 Captain America: Civil War', 'http://localhost:9090/files/download/captain_america3.webp', '超级英雄注册法案引发复仇者联盟内部分裂，美国队长与钢铁侠各自集结阵营展开对决。', '2016', '安东尼·罗素 / 乔·罗素', '克里斯·埃文斯 / 小罗伯特·唐尼 / 斯嘉丽·约翰逊 / 塞巴斯蒂安·斯坦', 5, '美国', '英语', '2016-05-06', '147分钟', 'tt3498820');
INSERT INTO `film` VALUES (27, '奇异博士 Doctor Strange', 'http://localhost:9090/files/download/doctor_strange1.webp', '外科医生史蒂芬·斯特兰奇在车祸后寻求治愈，却发现了魔法与多元宇宙的存在。', '2016', '斯科特·德瑞克森', '本尼迪克特·康伯巴奇 / 切瓦特·埃加福特 / 瑞秋·麦克亚当斯 / 蒂尔达·斯文顿', 4, '美国', '英语', '2016-11-04', '115分钟', 'tt1211837');
INSERT INTO `film` VALUES (28, '银河护卫队2 Guardians of the Galaxy Vol. 2', 'http://localhost:9090/files/download/guardians2.webp', '星爵发现自己的亲生父亲伊戈，银河护卫队必须再次团结面对新的威胁。', '2017', '詹姆斯·古恩', '克里斯·帕拉特 / 佐伊·索尔达娜 / 戴夫·巴蒂斯塔 / 库尔特·拉塞尔', 4, '美国', '英语', '2017-05-05', '136分钟', 'tt3896198');
INSERT INTO `film` VALUES (29, '蜘蛛侠：英雄归来 Spider-Man: Homecoming', 'http://localhost:9090/files/download/spiderman_homecoming.webp', '高中生彼得·帕克在托尼·史塔克的指导下，平衡校园生活与蜘蛛侠身份，对抗秃鹫。', '2017', '乔恩·沃茨', '汤姆·霍兰德 / 小罗伯特·唐尼 / 迈克尔·基顿 / 玛丽莎·托梅', 5, '美国', '英语', '2017-07-07', '133分钟', 'tt2250912');
INSERT INTO `film` VALUES (30, '雷神3：诸神黄昏 Thor: Ragnarok', 'http://localhost:9090/files/download/thor3.webp', '雷神索尔被囚禁在萨卡星，必须与绿巨人联手，阻止死亡女神海拉毁灭阿斯加德。', '2017', '塔伊加·维迪提', '克里斯·海姆斯沃斯 / 汤姆·希德勒斯顿 / 凯特·布兰切特 / 马克·鲁法洛', 4, '美国', '英语', '2017-11-03', '130分钟', 'tt3501632');
